public static boolean isSorted(Node<Integer> lst) {
    // משווים כל חוליה לחוליה שאחריה
    Node<Integer> p = lst;
    while (p != null && p.hasNext()) {
        if (p.getValue() > p.getNext().getValue()) {
            return false;
        }
        p = p.getNext();
    }
    return true;
}

public static int countLeaves(BinNode<Integer> t) {
    // עץ ריק — אין עלים; עלה — 1; אחרת — העלים משמאל ועוד העלים מימין
    if (t == null) {
        return 0;
    }
    if (!t.hasLeft() && !t.hasRight()) {
        return 1;
    }
    return countLeaves(t.getLeft()) + countLeaves(t.getRight());
}

public static Node<Integer> merge(Node<Integer> a, Node<Integer> b) {
    // חוליה ראשונה "דמה" — כך קל להוסיף בסוף; בכל שלב מעתיקים את הקטן מבין השניים
    Node<Integer> dummy = new Node<Integer>(0);
    Node<Integer> last = dummy;
    while (a != null && b != null) {
        if (a.getValue() <= b.getValue()) {
            last.setNext(new Node<Integer>(a.getValue()));
            a = a.getNext();
        } else {
            last.setNext(new Node<Integer>(b.getValue()));
            b = b.getNext();
        }
        last = last.getNext();
    }
    // מה שנשאר באחת השרשראות
    Node<Integer> rest = a;
    if (rest == null) {
        rest = b;
    }
    while (rest != null) {
        last.setNext(new Node<Integer>(rest.getValue()));
        last = last.getNext();
        rest = rest.getNext();
    }
    return dummy.getNext();
}

